(2297233, 313793, 52292, '<td valign="top">A very great photo! The focus is so good!</td>', 'A very great photo! The focus is so good!', '2006-04-08 09:02:56.000000', NULL, 1),
(2297236, 316738, 52292, '<td valign="top">Hej I want this China-Lego-Twn too! ;) Looks like a real city!</td>', 'Hej I want this China-Lego-Twn too! ;) Looks like a real city!', '2006-04-08 09:03:46.000000', NULL, 1),
