(2302735, 313588, 4010, '<td valign="top">Great shot.  How many times did you shoot this before catching the moment?  Looks like alot, by the look on the kids face.</td>', 'Great shot.  How many times did you shoot this before catching the moment?  Looks like alot, by the look on the kids face.', '2006-04-10 23:19:37.000000', NULL, 1),
(2302749, 316475, 35323, '<td valign="top">I hope you post this one for sell.  I love it!</td>', 'I hope you post this one for sell.  I love it!', '2006-04-10 23:25:35.000000', NULL, 1),
(2302772, 314785, 29011, '<td valign="top">Beatiful capture. Love the title ;)<br/>Bumping up.</td>', 'Beatiful capture. Love the title ;)Bumping up.', '2006-04-10 23:49:31.000000', NULL, 1),
(2302774, 316902, 29011, '<td valign="top">Great idea with the backlighting. Working with something so simple and getting something as artful as this.</td>', 'Great idea with the backlighting. Working with something so simple and getting something as artful as this.', '2006-04-10 23:50:24.000000', NULL, 1),
