(2302779, 315679, 29011, '<td valign="top">Very cute :)  Perfectly captured.</td>', 'Very cute :)  Perfectly captured.', '2006-04-10 23:51:35.000000', NULL, 1),
(2302785, 316213, 29011, '<td valign="top">Dont particularly see this as a children''s toy. Perhaps if you had a child hold it, it would be more apparent for this challenge.</td>', 'Dont particularly see this as a children''s toy. Perhaps if you had a child hold it, it would be more apparent for this challenge.', '2006-04-10 23:54:52.000000', NULL, 1),
(2302794, 315086, 29011, '<td valign="top">Seems as though this was lit up with a straight on flash. Perhaps an off camera light source would''ve been better, for less flat lighting.</td>', 'Seems as though this was lit up with a straight on flash. Perhaps an off camera light source would''ve been better, for less flat lighting.', '2006-04-10 23:58:03.000000', NULL, 1),
