(2303022, 316900, 42601, '<td valign="top">Nice idea putting the truck on a bigger one! I think the image has a little bit too much contrast IMO.</td>', 'Nice idea putting the truck on a bigger one! I think the image has a little bit too much contrast IMO.', '2006-04-11 02:43:04.000000', NULL, 1),
(2303024, 316696, 42601, '<td valign="top">I love it! Nice insight and great humour. Homer''s face is a little red for me though... dont know if that couldve been helped, but good shot nonetheless!</td>', 'I love it! Nice insight and great humour. Homer''s face is a little red for me though... dont know if that couldve been helped, but good shot nonetheless!', '2006-04-11 02:45:25.000000', NULL, 1),
(2303025, 316767, 42601, '<td valign="top">Like the setting, but the figurine is a little soft for me in terms of focus.</td>', 'Like the setting, but the figurine is a little soft for me in terms of focus.', '2006-04-11 02:46:51.000000', NULL, 1),
(2303026, 316859, 42601, '<td valign="top">It''s a nice shot, but not interesting enough to hold me for very long. Technically everything seems sound, (cept maybe the background is a little dull) but overall just not exciting enough. Give me action! Flames! Smoke! lol... could just be me. Good luck with the next challenge!! :)</td>', 'It''s a nice shot, but not interesting enough to hold me for very long. Technically everything seems sound, (cept maybe the background is a little dull) but overall just not exciting enough. Give me action! Flames! Smoke! lol... could just be me. Good luck with the next challenge!! :)', '2006-04-11 02:50:04.000000', NULL, 1),
(2303028, 316782, 42601, '<td valign="top">I like the DOF on this shot, but also overall. I think on its own the image might struggle if not placed in context, but thats not what this is about. Well done on a nice image and great idea.</td>', 'I like the DOF on this shot, but also overall. I think on its own the image might struggle if not placed in context, but thats not what this is about. Well done on a nice image and great idea.', '2006-04-11 02:51:35.000000', NULL, 1),
(2303029, 316637, 42601, '<td valign="top">Nice angle, nice mood. I''m not sure if the cropped off head is bothering me a little, but overall very good shot.</td>', 'Nice angle, nice mood. I''m not sure if the cropped off head is bothering me a little, but overall very good shot.', '2006-04-11 02:52:33.000000', NULL, 1),
(2303031, 316682, 42601, '<td valign="top">Bear''s. :) I like the setting you have created here - adding a bit of a story to an inaminate object. The lighting works for me. Nice! Good luck with the next challenge!</td>', 'Bear''s. :) I like the setting you have created here - adding a bit of a story to an inaminate object. The lighting works for me. Nice! Good luck with the next challenge!', '2006-04-11 02:54:14.000000', NULL, 1),
(2303034, 316736, 42601, '<td valign="top">When I first saw this challenge description I figured I would see one of these along the way. :) I like the crop, the tear, and the blue background which kind of lends to the sullen/sad mood you have intended. Overall, good shot and great capture!</td>', 'When I first saw this challenge description I figured I would see one of these along the way. :) I like the crop, the tear, and the blue background which kind of lends to the sullen/sad mood you have intended. Overall, good shot and great capture!', '2006-04-11 02:55:54.000000', NULL, 1),
(2303037, 316826, 42601, '<td valign="top">Nice idea! I think the foot is a little too high up in the pic for my liking though. Try cropping it a little bit under the foot and see if it doesn''t give you more attention to your subject (in this case, the foot on the pedal) I think there is still enough of the wheel left to discern what''s going on. Anyhow, great shot nonetheless! Good luck with the next challenge!</td>', 'Nice idea! I think the foot is a little too high up in the pic for my liking though. Try cropping it a little bit under the foot and see if it doesn''t give you more attention to your subject (in this case, the foot on the pedal) I think there is still enough of the wheel left to discern what''s going on. Anyhow, great shot nonetheless! Good luck with the next challenge!', '2006-04-11 02:57:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2303040, 316580, 42601, '<td valign="top">I dont know if it was your intention to portray the puppet in the foreground as a spectator but that is how I see it. Well done on a great idea and execution. One thing, if the puppet was indeed placed for such a purpose, I think you could have done without the strings. Apart from that little niggle, well done! :)</td>', 'I dont know if it was your intention to portray the puppet in the foreground as a spectator but that is how I see it. Well done on a great idea and execution. One thing, if the puppet was indeed placed for such a purpose, I think you could have done without the strings. Apart from that little niggle, well done! :)', '2006-04-11 03:01:12.000000', NULL, 1),
(2303045, 316852, 42601, '<td valign="top">Okay. First off, I love the backlighting and positioning of your doll in the overall composition. Your title amuse me: "Cheetah" ? Is this/was a cheetah? Or is it a monkey and its name is Cheetah? I think what also appeals to me is the fact that "cheetah" is so worn at the bottom, yet still remains a loyal friend. Instead of placing him in a sad/depressed setting like most ppl did, you chose a more happy approach, the kind that says: "I''ll always be your mate no matter what" Well done on a great shot. It may be plain and simple to the naked eye, but I like whats lying underneath.</td>', 'Okay. First off, I love the backlighting and positioning of your doll in the overall composition. Your title amuse me: "Cheetah" ? Is this/was a cheetah? Or is it a monkey and its name is Cheetah? I think what also appeals to me is the fact that "cheetah" is so worn at the bottom, yet still remains a loyal friend. Instead of placing him in a sad/depressed setting like most ppl did, you chose a more happy approach, the kind that says: "I''ll always be your mate no matter what" Well done on a great shot. It may be plain and simple to the naked eye, but I like whats lying underneath.', '2006-04-11 03:06:06.000000', NULL, 1),
(2303046, 316627, 42601, '<td valign="top">Mmmhh... this shot seems to be technically sound, yet I really fail to see the toy element. Maybe I have just never seen a toy like this before. If it''s similar to building blocks, I think this pic lacks that ''fun'' element a little bit. Still, it''s probably because i''m unfamiliar with the toy. Good shot nonetheless!</td>', 'Mmmhh... this shot seems to be technically sound, yet I really fail to see the toy element. Maybe I have just never seen a toy like this before. If it''s similar to building blocks, I think this pic lacks that ''fun'' element a little bit. Still, it''s probably because i''m unfamiliar with the toy. Good shot nonetheless!', '2006-04-11 03:09:28.000000', NULL, 1),
(2303048, 316563, 42601, '<td valign="top">I like this. Its simple, yet there''s more than enough to hold me to this picture. Nice DOF! Good luck with the next challenge!</td>', 'I like this. Its simple, yet there''s more than enough to hold me to this picture. Nice DOF! Good luck with the next challenge!', '2006-04-11 03:11:18.000000', NULL, 1),
(2303050, 314840, 42601, '<td valign="top">I swear, if I had a couple of beers before I voted I would find this a little disturbing... lol! Thats not to say it''s not intriguing. On the contrary, I can''t seem to stop looking at it. I love the fish-eye approach, the higher angle, the setup, the shot, the title. If anything, I think you have captured ''alone'' in three ways: the desolate background, the bunny, and your main subject. There are two slight things that deter me from shouting brilliance though. 1. It doesnt portray this particular challenge (toys) a 100% for me, and thats to say in essence. If this was for a dream challenge or something, I wouldve yielded. And no 2: I think you couldve cropped a tad off the right for balance. Great shot!!</td>', 'I swear, if I had a couple of beers before I voted I would find this a little disturbing... lol! Thats not to say it''s not intriguing. On the contrary, I can''t seem to stop looking at it. I love the fish-eye approach, the higher angle, the setup, the shot, the title. If anything, I think you have captured ''alone'' in three ways: the desolate background, the bunny, and your main subject. There are two slight things that deter me from shouting brilliance though. 1. It doesnt portray this particular challenge (toys) a 100% for me, and thats to say in essence. If this was for a dream challenge or something, I wouldve yielded. And no 2: I think you couldve cropped a tad off the right for balance. Great shot!!', '2006-04-11 03:19:03.000000', NULL, 1),
(2303053, 316684, 42601, '<td valign="top">Nice angle, nice dof. I cant say anymore really... lol! There;s absolutely nothing wrong with this shot technically. But i guess it''s just not a ground-breaker IMO.</td>', 'Nice angle, nice dof. I cant say anymore really... lol! There;s absolutely nothing wrong with this shot technically. But i guess it''s just not a ground-breaker IMO.', '2006-04-11 03:23:10.000000', NULL, 1),
(2303071, 315229, 52765, '<td valign="top">If you would have done some saturation and levels/curves on this but obeying the basic rules I think this picture would have stood out a mile. It is screaming potential but just doesnt have that kick.<br/>6 but I think it could have been at least a 9/10</td>', 'If you would have done some saturation and levels/curves on this but obeying the basic rules I think this picture would have stood out a mile. It is screaming potential but just doesnt have that kick.6 but I think it could have been at least a 9/10', '2006-04-11 03:59:03.000000', NULL, 1),
