INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2305767, 316755, 31889, '<td valign="top">Well done again.  Your submissions have been very good, (except for one), since getting a dslr.</td>', 'Well done again.  Your submissions have been very good, (except for one), since getting a dslr.', '2006-04-12 05:44:57.000000', NULL, 0),
(2305780, 316683, 36091, '<td valign="top">Congrats on 8th place!</td>', 'Congrats on 8th place!', '2006-04-12 05:50:08.000000', NULL, 0),
(2305795, 313793, 24767, '<td valign="top">Thanks for the comments guys.<br/> <br/>About the brick - if I had a red one, I would have, but all I could findin my collection was brown...   :-(<br/> <br/>About the focus - I was trying to lead the eye to the brick, and to this end used the lens (85mm tilt n shift) at its maximum tilt, which achieved the diagonal plane of focus, and the oof corners.<br/> <br/>30th, not bad.</td>', 'Thanks for the comments guys. About the brick - if I had a red one, I would have, but all I could findin my collection was brown...   :-( About the focus - I was trying to lead the eye to the brick, and to this end used the lens (85mm tilt n shift) at its maximum tilt, which achieved the diagonal plane of focus, and the oof corners. 30th, not bad.', '2006-04-12 06:02:50.000000', NULL, 0),
(2305808, 313793, 16241, '<td valign="top">cute idea!</td>', 'cute idea!', '2006-04-12 06:11:46.000000', NULL, 0),
